mapper.select:
/* RiskAi01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* RiskAi01Mapper.selectDerivation */
SELECT
    A.IMG_CHAT_JSON
  , A.SUPP_DESC
  , A.IMG_CONFIRMED
  , A.HAZARD_JSON
  , A.MEASURE_JSON
  , A.CITATION_JSON
  , A.VERBATIM_JSON
  , A.ABSTAINED
FROM TB_RISK_AI_DERIVATION A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

mapper.insert:
/* RiskAi01Mapper.insertDerivationIfAbsent */
INSERT IGNORE INTO TB_RISK_AI_DERIVATION
(
    CMPNY_CD
  , SITE_CD
  , PROCESS_CD
  , ASSESSMENT_CD
  , IMG_ANALYZE_CNT
  , DERIVE_CNT
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{cmpnyCd}
  , #{siteCd}
  , #{processCd}
  , #{assessmentCd}
  , 0
  , 0
  , #{userCd}
  , NOW()
)

mapper.delete:
/* RiskAi01Mapper.deleteDerivation */
DELETE FROM TB_RISK_AI_DERIVATION
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}

/* RiskAi01Mapper.deleteUnsavedDerivation */
DELETE FROM TB_RISK_AI_DERIVATION
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND SAVED_YN = 'N'

mapper.update:
/* RiskAi01Mapper.updateSavedYn */
UPDATE TB_RISK_AI_DERIVATION
SET
    SAVED_YN = #{savedYn}
  , UPDATE_NO = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}

/* RiskAi01Mapper.updateImgChatJson */
UPDATE TB_RISK_AI_DERIVATION
SET
    IMG_CHAT_JSON = #{imgChatJson}
  , SAVED_YN = 'N'
  , UPDATE_NO = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}

/* RiskAi01Mapper.updateSuppDesc */
UPDATE TB_RISK_AI_DERIVATION
SET
    SUPP_DESC = #{suppDesc}
  , SAVED_YN = 'N'
  , UPDATE_NO = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}

/* RiskAi01Mapper.updateImgConfirmed */
UPDATE TB_RISK_AI_DERIVATION
SET
    IMG_CONFIRMED = #{imgConfirmed}
  , UPDATE_NO = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}

/* RiskAi01Mapper.updateDeriveResult */
UPDATE TB_RISK_AI_DERIVATION
SET
    HAZARD_JSON = #{hazardJson}
  , MEASURE_JSON = NULL
  , CITATION_JSON = #{citationJson}
  , VERBATIM_JSON = #{verbatimJson}
  , ABSTAINED = #{abstained}
  , SAVED_YN = 'N'
  , LAST_DERIVE_BY = #{userCd}
  , LAST_DERIVE_DATE = NOW()
  , UPDATE_NO = #{userCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
